r1[t_] := {6 Cos[t]^3, 6 Sin[t]^3}
r2[t_] := {2 t - 2 Sin[t], 2 - 2 Cos[t]}
ParametricPlot[{r1[t], r2[t]}, {t, 0, 2 Pi}]

sol = FindRoot[r1[a] == r2[b], {a, 0.8}, {b, 1.8}]
ta = a /. sol;
tc = b /. sol;

A1 = Integrate[(1 - Cos[t]) D[t - Sin[t], t], {t, 0, tc}];
A2 = Integrate[(3 Sin[t]^3) D[3 Cos[t]^3, t], {t, ta, 0}];
